import json as _json, os as _os
from uhm_runtime import stdin_path as _stdin_path, resource as _resource
_os.environ['UHM_PROGRAM_INPUTS']=_json.dumps([{'path':str(_resource('input_1').read_path),'access':'read_only'},{'path':str(_resource('input_2').read_path),'access':'read_only'}],separators=(',',':'))
_os.environ['UHM_PROGRAM_OUTPUTS']=_json.dumps([{'path':str(_resource('output_1').write_path)}],separators=(',',':'))
if _stdin_path is not None: _os.environ['UHM_PROGRAM_LOCAL_INPUT']=str(_stdin_path)
import json,os
ins=json.loads(os.environ['UHM_PROGRAM_INPUTS']); o=json.loads(os.environ['UHM_PROGRAM_OUTPUTS'])[0]['path']; result={}
for item in ins: result.update(json.load(open(item['path'],encoding='utf-8')))
open(o,'w',encoding='utf-8').write(json.dumps(result,sort_keys=True)+'\n')

